- How to adapt with a per-segment penalty or bonus c?
- Can we accelerate with divide-and-conquer optimization if quadrangle inequality holds?

## Why This Is Asked

Tests dynamic programming on partitioning a string into numeric substrings, including numeric parsing and reconstruction, a common interview pattern.

## Key Concepts

- DP on string partitions with exact k blocks
- Efficient substring value computation and leading-zero handling
- Path reconstruction via parent pointers
- Time/space trade-offs: O(n^2 k) time, O(nk) space

## Code Example

```javascript
function maxSumPartition(s, k) {
  const n = s.length;
  // val[i][j] = value of s[i..j-1]
  const val = Array.from({ length: n+1 }, () => Array(n+1).fill(0));
  for (let i = 0; i < n; i++) {
    if (s[i] === '0') { val[i][i+1] = 0; continue; }
    let cur = 0;
    for (let j = i; j < n; j++) {
      cur = cur*10 + (s.charCodeAt(j) - 48);
      val[i][j+1] = cur;
    }
  }
  const dp = Array.from({ length: n+1 }, () => Array(k+1).fill(-Infinity));
  const par = Array.from({ length: n+1 }, () => Array(k+1).fill(-1));
  for (let i = 1; i <= n; i++) dp[i][1] = val[0][i];
  for (let t = 2; t <= k; t++) {
    for (let i = t; i <= n; i++) {
      for (let j = t-1; j < i; j++) {
        if (s[j] === '0' && i - j > 1) continue;
        const cand = dp[j][t-1] + val[j][i];
        if (cand > dp[i][t]) { dp[i][t] = cand; par[i][t] = j; }
      }
    }
  }
  // reconstruct cuts
  const cuts = [];
  let i = n, t = k;
  while (t > 0) {
    const j = par[i][t];
    cuts.push(i);
    i = j;
    t--;
  }
  cuts.push(0);
  cuts.reverse();
  return { sum: dp[n][k], cuts };
}
```

## Follow-up Questions

- How would you adapt to allow at most k blocks instead of exactly k?
- How would you optimize for very large n or larger k (space/time optimizations, early pruning)?

## Why This Is Asked

This tests a standard DP with an adjacency constraint and a limit on picks, plus reconstruction.

## Key Concepts

- DP over i and t with i-2 due to adjacency
- Reconstruction via a take/parent trace
- Space/time trade-offs; potential optimizations

## Code Example

```javascript
function maxNonAdjSum(a, k) {
  const n = a.length;
  const dp = Array.from({length: n+1}, ()=>Array(k+1).fill(0));
  const take = Array.from({length: n+1}, ()=>Array(k+1).fill(false));
  for (let i = 1; i <= n; i++) {
    for (let t = 0; t <= k; t++) {
      dp[i][t] = dp[i-1][t];
      if (t > 0 && i >= 2 && dp[i-2][t-1] + a[i-1] > dp[i][t]) {
        dp[i][t] = dp[i-2][t-1] + a[i-1];
        take[i][t] = true;
      }
    }
  }
  // Reconstruct indices
  const indices = [];
  let i = n, t = k;
  while (i > 0 && t > 0) {
    if (take[i][t]) {
      indices.push(i-1);
      i -= 2;
      t--;
    } else {
      i--;
    }
  }
  return { maxProfit: dp[n][k], indices: indices.reverse() };
}
```

## Why This Is Asked
Tests DP setup for segment selection with non-adjacency and reconstruction, a common beginner DP pattern with a twist.

## Key Concepts
- DP over index i and blocks t
- Enforce non-adjacency via s-2 reference
- Prefix sums for O(1) subarray sums
- Reconstruction pointers for endpoints
- Time/space trade-offs; possible optimization to O(nk) time and O(n) space per k

## Code Example
```javascript
function maxKSubarraysSum(A, k) {
  const n = A.length;
  const P = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) P[i + 1] = P[i] + A[i];

  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const take = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-1));
  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 0; t <= k; t++) {
      // skip i
      dp[i][t] = Math.max(dp[i][t], dp[i - 1][t]);
      if (t > 0) {
        for (let s = 1; s <= i; s++) {
          const sum = P[i] - P[s - 1];
          const prev = (s >= 2) ? dp[s - 2][t - 1] : (t - 1 === 0 ? 0 : -Infinity);
          const cand = sum + prev;
          if (cand > dp[i][t]) {
            dp[i][t] = cand;
            take[i][t] = s;
          }
        }
      }
    }
  }
  // reconstruction would trace back using 'take' from (n, bestT)
  return { maxSum: dp[n][0], blocks: [] };
}
```

## Why This Is Asked
Tests interval DP with exactly k block selection, reconstruction, and non-adjacent constraint handling. Requires precomputing interval values (max-min) and a clean end-at-i transition that accounts for the gap requirement.

## Key Concepts
- Interval DP with exactly k non-adjacent blocks
- Precomputation of val(l,r) = max(A[l..r]) - min(A[l..r]) using O(n²) sliding window enumeration
- Reconstruction pointers to retrieve endpoints
- Time complexity: O(n²) precomputation + O(kn²) DP; Space: O(n²) for val table + O(n·k) for DP
- Edge cases: k > ⌊n/2⌋ (impossible, return error), empty arrays (return 0)

## Code Example
```javascript
function maxKSumIntervals(A, k) {
  const n = A.length;
  const val = Array.from({ length: n }, () => Array(n).fill(0));

  for (let l = 0; l < n; l++) {
    let min = A[l], max = A[l];
    for (let r = l; r < n; r++) {
      min = Math.min(min, A[r]);
      max = Math.max(max, A[r]);
      val[l][r] = max - min;
    }
  }

  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const parent = Array.from({ length: n + 1 }, () => Array(k + 1).fill(null));

  for (let i = 0; i <= n; i++) dp[i][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      dp[i][t] = dp[i-1][t];
      parent[i][t] = { skip: true };

      for (let j = 1; j <= i; j++) {
        const prev = j >= 2 ? dp[j-2][t-1] : (t === 1 ? 0 : -Infinity);
        if (prev === -Infinity) continue;
        const curr = prev + val[j-1][i-1];
        if (curr > dp[i][t]) {
          dp[i][t] = curr;
          parent[i][t] = { start: j, end: i, prev: j - 2 };
        }
      }
    }
  }

  const intervals = [];
  let i = n, t = k;
  while (t > 0 && parent[i][t]) {
    const p = parent[i][t];
    if (!p.skip) {
      intervals.push([p.start, p.end]);
      i = p.prev;
      t--;
    } else {
      i--;
    }
  }

  return { maxValue: dp[n][k], intervals: intervals.reverse() };
}
```

## Why This Is Asked
This introduces selecting non-covering, fixed-cost segments, a natural DP with a running max optimization. It tests understanding of prefix sums, state pruning, and reconstruction.

## Key Concepts
- Prefix sums to compute segment sums in O(1)
- DP over i and t with exactly t segments
- Running maximum best[t] to avoid O(n) inner loop
- Path reconstruction to recover endpoints

## Code Example
```javascript
function maxValueSegments(A, k, c){
  const n = A.length;
  const S = Array(n+1).fill(0);
  for(let i=1;i<=n;i++) S[i]=S[i-1]+A[i-1];
  const negInf = -1e18;
  const dp = Array.from({length:n+1},()=>Array(k+1).fill(negInf));
  const par = Array.from({length:n+1},()=>Array(k+1).fill([-1,-1]));
  dp[0][0]=0;
  for(let t=1;t<=k;t++) par[0][t]=[-1,-1];
  for(let t=1;t<=k;t++){
    let best = negInf; // max of dp[m][t-1]-S[m]
    for(let i=1;i<=n;i++){
      best = Math.max(best, dp[i-1][t-1]-S[i-1]);
      const val = best + S[i] - c;
      if(val > dp[i][t]){ dp[i][t]=val; par[i][t]=[i-1,-1]; }
      if(dp[i-1][t] > dp[i][t]){ dp[i][t]=dp[i-1][t]; par[i][t]=[i-1,t]; }
    }
  }
  // reconstruction (simple version)
  let i=n, t=k, ends=[];
  while(t>0){
    const [pi, pt] = par[i][t] || [-1,-1];
    if(pi===-1) break;
    // approximate end at i, start at some m where dp[m][t-1]-S[m] was max
    // for brevity here, return only values; full reconstruction can be added as needed
    ends.push(i);
    i = pi; t--;
  }
  return { value: dp[n][k], ends: ends.reverse() };
}
```

